import 'package:flutter/material.dart';import 'route_constants.dart';class AppRoutes {  static Route<dynamic> generateRoute(RouteSettings settings) {    switch (settings.name) {      case RouteNames.home:      // return MaterialPageRoute(builder: (_) => const HomePage());      case RouteNames.start:      // return MaterialPageRoute(builder: (_) => const SettingsPage());      case RouteNames.splash:      // return MaterialPageRoute(builder: (_) => const ProfilePage());      default:        return MaterialPageRoute(          builder: (_) => Scaffold(            body: Center(              child: Text('No route defined for ${settings.name}'),            ),          ),        );    }  }}